		FROM inbox
		WHERE sender_id <> `+deleteUserPlaceholder(1)+`
			AND receiver_id <> `+deleteUserPlaceholder(2), userID, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	inboxIDs := make([]int32, 0)
	for rows.Next() {
		var (
