			messageRaw []byte
		)
		if err := rows.Scan(&inboxID, &messageRaw); err != nil {
			return nil, err
		}
		if len(messageRaw) == 0 {
			continue
		}

		message := &storepb.InboxMessage{}
		if err := protojsonUnmarshaler.Unmarshal(messageRaw, message); err != nil {
			return nil, err
